-- Clamp a value between min and max
local function clamp(val, min_val, max_val)
    if val < min_val then return min_val end
    if val > max_val then return max_val end
    return val
end

-- Simple matrix multiplication for 2D matrices
local function matmul(A, B)
    local rowsA = #A
    local colsA = #A[1]
    local rowsB = #B
    local colsB = #B[1]
    assert(colsA == rowsB, "Matrix dimensions must agree for multiplication")
    local result = {}
    for i = 1, rowsA do
        result[i] = {}
        for j = 1, colsB do
            local sum = 0
            for k = 1, colsA do
                sum = sum + A[i][k] * B[k][j]
            end
            result[i][j] = sum
        end
    end
    return result
end

