-- Predictive Models: Linear and Nonlinear Regression
--------------------------------------------------------------------------------

-- Linear regression model using least squares
local LinearRegression = {}
LinearRegression.__index = LinearRegression

function LinearRegression.new()
    local self = setmetatable({}, LinearRegression)
    self.x = {}
    self.y = {}
    self.slope = 0
    self.intercept = 0
    return self
end

function LinearRegression:add_point(xi, yi)
    table.insert(self.x, xi)
    table.insert(self.y, yi)
end

function LinearRegression:train()
    local n = #self.x
    if n < 2 then
        debug_log("Not enough data points for linear regression")
        return
    end
    local sum_x, sum_y, sum_xy, sum_x2 = 0, 0, 0, 0
    for i = 1, n do
        sum_x = sum_x + self.x[i]
        sum_y = sum_y + self.y[i]
        sum_xy = sum_xy + self.x[i] * self.y[i]
        sum_x2 = sum_x2 + self.x[i] * self.x[i]
    end
    local denominator = n * sum_x2 - sum_x * sum_x
    if denominator == 0 then
        debug_log("Denominator zero in linear regression")
        return
    end
    self.slope = (n * sum_xy - sum_x * sum_y) / denominator
    self.intercept = (sum_y - self.slope * sum_x) / n
    debug_log("Linear regression trained: slope=", self.slope, " intercept=", self.intercept)
end

function LinearRegression:predict(x)
    return self.slope * x + self.intercept
end

-- Nonlinear regression using simple polynomial fit (degree 2)
local NonlinearRegression = {}
NonlinearRegression.__index = NonlinearRegression

function NonlinearRegression.new()
    local self = setmetatable({}, NonlinearRegression)
    self.x = {}
    self.y = {}
    self.coeffs = {0, 0, 0} -- a, b, c for ax^2 + bx + c
    return self
end

function NonlinearRegression:add_point(xi, yi)
    table.insert(self.x, xi)
    table.insert(self.y, yi)
end

function NonlinearRegression:train()
    local n = #self.x
    if n < 3 then
        debug_log("Not enough data points for nonlinear regression")
        return
    end
    local sum_x = 0
    local sum_x2 = 0
    local sum_x3 = 0
    local sum_x4 = 0
    local sum_y = 0
    local sum_xy = 0
    local sum_x2y = 0

    for i = 1, n do
        local xi = self.x[i]
        local yi = self.y[i]
        local x2 = xi * xi
        sum_x = sum_x + xi
        sum_x2 = sum_x2 + x2
        sum_x3 = sum_x3 + x2 * xi
        sum_x4 = sum_x4 + x2 * x2
        sum_y = sum_y + yi
        sum_xy = sum_xy + xi * yi
        sum_x2y = sum_x2y + x2 * yi
    end

    local denom = (n * (sum_x2 * sum_x4 - sum_x3 * sum_x3)
                  - sum_x * (sum_x * sum_x4 - sum_x2 * sum_x3)
                  + sum_x2 * (sum_x * sum_x3 - sum_x2 * sum_x2))

    if denom == 0 then
        debug_log("Denominator zero in nonlinear regression")
        return
    end

    local a = ( (sum_y * (sum_x2 * sum_x4 - sum_x3 * sum_x3)
                - sum_x * (sum_xy * sum_x4 - sum_x3 * sum_x2y)
                + sum_x2 * (sum_xy * sum_x3 - sum_x2 * sum_x2y)) / denom)

    local b = ( (n * (sum_xy * sum_x4 - sum_x3 * sum_x2y)
                - sum_y * (sum_x * sum_x4 - sum_x2 * sum_x3)
                + sum_x2 * (sum_x * sum_x2y - sum_xy * sum_x2)) / denom)

    local c = ( (n * (sum_x2 * sum_x2y - sum_xy * sum_x3)
                - sum_x * (sum_x * sum_x2y - sum_xy * sum_x2)
                + sum_y * (sum_x * sum_x3 - sum_x2 * sum_x2)) / denom)

    self.coeffs = {a, b, c}
    debug_log("Nonlinear regression trained: a=", a, " b=", b, " c=", c)
end

function NonlinearRegression:predict(x)
    local a, b, c = table.unpack(self.coeffs)
    return a + b * x + c * x * x
end

--------------------------------------------------------------------------------
-- Kalman Filter for Latency Smoothing
--------------------------------------------------------------------------------

local KalmanFilter = {}
KalmanFilter.__index = KalmanFilter

function KalmanFilter.new(process_variance, estimated_measurement_variance)
    local self = setmetatable({}, KalmanFilter)
    self.process_variance = process_variance or 1e-5
    self.estimated_measurement_variance = estimated_measurement_variance or 1e-2
    self.posteri_estimate = 0
    self.posteri_error_estimate = 1
    return self
end

function KalmanFilter:update(measurement)
    -- Prediction update
    local priori_estimate = self.posteri_estimate
    local priori_error_estimate = self.posteri_error_estimate + self.process_variance

    -- Measurement update
    local kalman_gain = priori_error_estimate / (priori_error_estimate + self.estimated_measurement_variance)
    self.posteri_estimate = priori_estimate + kalman_gain * (measurement - priori_estimate)
    self.posteri_error_estimate = (1 - kalman_gain) * priori_error_estimate

    debug_log("Kalman update: measurement=", measurement, " estimate=", self.posteri_estimate)
    return self.posteri_estimate
end

--------------------------------------------------------------------------------
-- Exponential Moving Average for Bandwidth Prediction
--------------------------------------------------------------------------------

local EMA = {}
EMA.__index = EMA

function EMA.new(alpha)
    local self = setmetatable({}, EMA)
    self.alpha = alpha or 0.1
    self.current = nil
    return self
end

function EMA:update(value)
    if self.current == nil then
        self.current = value
    else
        self.current = self.alpha * value + (1 - self.alpha) * self.current
    end
    debug_log("EMA update: value=", value, " current=", self.current)
    return self.current
end

--------------------------------------------------------------------------------
-- Adaptive Jitter Buffer
--------------------------------------------------------------------------------

local AdaptiveJitterBuffer = {}
AdaptiveJitterBuffer.__index = AdaptiveJitterBuffer

function AdaptiveJitterBuffer.new()
    local self = setmetatable({}, AdaptiveJitterBuffer)
    self.buffer = {}
    self.target_delay = 50 -- ms target delay
    self.max_delay = 200 -- ms max delay
    self.min_delay = 10 -- ms min delay
    self.current_delay = self.target_delay
    return self
end

function AdaptiveJitterBuffer:add_packet(packet, arrival_time)
    table.insert(self.buffer, {packet=packet, arrival=arrival_time})
    -- Remove packets older than current_delay
    local cutoff = arrival_time - self.current_delay
    while #self.buffer > 0 and self.buffer[1].arrival < cutoff do
        table.remove(self.buffer, 1)
    end
    debug_log("JitterBuffer add_packet: buffer_size=", #self.buffer, " current_delay=", self.current_delay)
end

function AdaptiveJitterBuffer:get_packet()
    if #self.buffer == 0 then return nil end
    return table.remove(self.buffer, 1).packet
end

function AdaptiveJitterBuffer:adjust_delay(jitter)
    -- Adjust delay based on jitter (ms)
    local adjustment = jitter * 1.5
    self.current_delay = clamp(self.current_delay + adjustment, self.min_delay, self.max_delay)
    debug_log("JitterBuffer adjust_delay: jitter=", jitter, " new_delay=", self.current_delay)
end

--------------------------------------------------------------------------------
-- Packet Prioritization Logic
--------------------------------------------------------------------------------

local PacketPrioritizer = {}
PacketPrioritizer.__index = PacketPrioritizer

function PacketPrioritizer.new()
    local self = setmetatable({}, PacketPrioritizer)
    self.priority_queue = {}
    return self
end

function PacketPrioritizer:add_packet(packet, priority_score)
    -- Insert packet in priority queue sorted by priority_score descending
    local inserted = false
    for i, item in ipairs(self.priority_queue) do
        if priority_score > item.priority then
            table.insert(self.priority_queue, i, {packet=packet, priority=priority_score})
            inserted = true
            break
        end
    end
    if not inserted then
        table.insert(self.priority_queue, {packet=packet, priority=priority_score})
    end
    debug_log("PacketPrioritizer add_packet: priority_score=", priority_score, " queue_size=", #self.priority_queue)
end

function PacketPrioritizer:get_next_packet()
    if #self.priority_queue == 0 then return nil end
    return table.remove(self.priority_queue, 1).packet
end

